package com.studyspace.security;
import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.Base64; import java.util.Map; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { @Value("${app.jwt-secret}") private String secret; private final ObjectMapper mapper; public JwtService(ObjectMapper mapper){this.mapper=mapper;}
 private String sign(String data) { try { Mac mac=Mac.getInstance("HmacSHA256"); mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256")); return Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(data.getBytes(StandardCharsets.UTF_8))); } catch(Exception e){throw new IllegalStateException(e);} }
 public String create(String userId) { try { String h=Base64.getUrlEncoder().withoutPadding().encodeToString(mapper.writeValueAsBytes(Map.of("alg","HS256","typ","JWT"))); String p=Base64.getUrlEncoder().withoutPadding().encodeToString(mapper.writeValueAsBytes(Map.of("sub",userId,"exp",Instant.now().getEpochSecond()+604800))); String data=h+"."+p; return data+"."+sign(data); } catch(Exception e){throw new IllegalStateException(e);} }
 public String validateAndGetUser(String token) { try { String[] p=token.split("\\."); if(p.length!=3 || !java.security.MessageDigest.isEqual(sign(p[0]+"."+p[1]).getBytes(StandardCharsets.UTF_8),p[2].getBytes(StandardCharsets.UTF_8))) return null; Map<?,?> payload=mapper.readValue(Base64.getUrlDecoder().decode(p[1]),Map.class); Object sub=payload.get("sub"), exp=payload.get("exp"); if(sub==null||!(exp instanceof Number)||((Number)exp).longValue()<Instant.now().getEpochSecond()) return null; return String.valueOf(sub); } catch(Exception e){return null;} }
}